from Crypto.Cipher import AES
key=bytes(range(16))
secret='nto{3cb_byt3_4t_4_t1m3_0r4cl3}'.encode()
def oracle(inp):
    return AES.new(key,AES.MODE_ECB).encrypt((inp+secret+b'\x00'*16)[: (len(inp+secret)+15)//16*16])
known=b''
bs=16
for i in range(len(secret)):
    pad=b'A'*(bs-1-(i%bs))
    target=oracle(pad)[:bs*(i//bs+1)][-bs:]
    for c in range(256):
        if oracle(pad+known+bytes([c]))[:bs*(i//bs+1)][-bs:]==target:
            known+=bytes([c]); break
print(known.decode())
